import threading, time, unittest
from cachetools import Cache, LRUCache, cached, cachedmethod

class DebugTests(unittest.TestCase):

    def exercise(self, info, method, hot=False):
        entered = threading.Event()
        release = threading.Event()
        other = threading.Event()
        calls = []
        cache = LRUCache(128)
        cond = threading.Condition()
        errors = []

        def body(key):
            calls.append(key)
            if key == 'held':
                entered.set()
                release.wait(4)
            if key == 'other':
                other.set()
            return key
        if method:

            class Owner:

                def __init__(self):
                    self.cache = cache
                    self.cond = cond

                @cachedmethod(lambda self: self.cache, condition=lambda self: self.cond, info=info)
                def run(self, key):
                    return body(key)
            f = Owner().run
        else:
            f = cached(cache, condition=cond, info=info)(body)
        if hot:
            f('other')
            other.clear()

        def call(key):
            try:
                f(key)
            except Exception as e:
                errors.append(repr(e))
        first = threading.Thread(target=call, args=('held',))
        second = threading.Thread(target=call, args=('other',))
        try:
            first.start()
            self.assertTrue(entered.wait(2))
            second.start()
            if hot:
                second.join(1)
                self.assertFalse(second.is_alive(), 'cached unrelated key blocked although no eviction occurs')
            else:
                self.assertTrue(other.wait(1), 'unrelated cache miss blocked although no eviction occurs')
        finally:
            release.set()
            first.join(5)
            second.join(5)
        self.assertFalse(errors, errors)
        self.assertFalse(first.is_alive() or second.is_alive())
        self.assertEqual(calls.count('held'), 1)

    def test_independent_keys_and_cached_hits(self):
        for info in [False, True]:
            for method in [False, True]:
                for hot in [False, True]:
                    with self.subTest(info=info, method=method, hot=hot):
                        self.exercise(info, method, hot)

    def test_same_key_suppression_and_exception_cleanup(self):
        for info in [False, True]:
            calls = []
            cond = threading.Condition()
            start = threading.Event()
            release = threading.Event()

            @cached(Cache(20), condition=cond, info=info)
            def f(k):
                calls.append(k)
                start.set()
                release.wait(2)
                return k
            workers = [threading.Thread(target=lambda: f(4)) for _ in range(5)]
            try:
                for w in workers:
                    w.start()
                self.assertTrue(start.wait(1))
                time.sleep(0.03)
            finally:
                release.set()
                for w in workers:
                    w.join(3)
            self.assertEqual(calls, [4])
            self.assertTrue(all((not w.is_alive() for w in workers)))
            if info:
                self.assertEqual(f.cache_info().misses, 1)
            attempts = []

            @cached(Cache(20), condition=threading.Condition(), info=info)
            def g(k):
                attempts.append(k)
                if len(attempts) == 1:
                    raise ValueError('original failure')
                return k
            with self.assertRaises(ValueError):
                g(3)
            self.assertEqual(g(3), 3)
def run(task,phase):
    suite=unittest.defaultTestLoader.loadTestsFromTestCase(DebugTests)
    result=unittest.TextTestRunner(verbosity=2).run(suite)
    return result.wasSuccessful(),result.testsRun

